import{_ as o,o as a,c as t,ag as r}from"./chunks/framework.B2Q7dRKp.js";const p=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1778097578000}'),l={name:"changelog.md"};function i(s,e,d,n,c,u){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>What changed in each release. For the raw commit log, see the <a href="https://github.com/bohmaan/AxgstAIO/releases" target="_blank" rel="noreferrer">GitHub releases</a>.</p><h2 id="v2-0-0-—-major-rework" tabindex="-1">v2.0.0 — Major rework <a class="header-anchor" href="#v2-0-0-—-major-rework" aria-label="Permalink to &quot;v2.0.0 — Major rework&quot;">​</a></h2><ul><li>New module: <strong>Mediaexpert</strong> (PL) — guest checkout + tpay card payment.</li><li><strong>Trimmed module set</strong> to 16 supported sites + Queue-it. Removed: catchyourcards, colorskates, dfn, footdistrict, ipzs, mueller, pagro, crocs.</li><li><strong>Shared public webhook</strong> — every successful checkout posts to one Discord channel (Title / Store / Product / Size / Method / Price / Mode). Failed checkouts not posted publicly. User webhooks add Account / Order ID / Payment URL.</li><li><strong>Unified console output</strong> — same event vocabulary, colors, and <code>[Site]</code> prefix across every module.</li><li><strong>Unified CSV</strong> — single header used by every module; card columns kept even where unused. Sample at <code>tasks.example.csv</code>.</li><li><strong>Docs rewrite</strong> — every site page in the same compact format (Code / Region / Modes / Payment / Notes / CSV row).</li></ul><h2 id="v1-9-0-—-solebox-proshop-modules" tabindex="-1">v1.9.0 — Solebox + Proshop modules <a class="header-anchor" href="#v1-9-0-—-solebox-proshop-modules" aria-label="Permalink to &quot;v1.9.0 — Solebox + Proshop modules&quot;">​</a></h2><h3 id="solebox" tabindex="-1">Solebox <a class="header-anchor" href="#solebox" aria-label="Permalink to &quot;Solebox&quot;">​</a></h3><ul><li>New module: <a href="/AxgstAIO-docs/sites/solebox">Solebox</a> (<code>solebox</code> / <code>sb</code>) — EU sneaker store.</li><li><strong><code>buy</code> mode</strong> — login, hold the requested EU size, webhook the logged-in checkout link. Finish address + card in browser.</li><li><strong><code>register</code> mode</strong> — creates the account and logs in. Subsequent <code>buy</code> tasks skip registration.</li><li><strong><code>login</code> mode</strong> — verify credentials and refresh the cached session.</li><li>Cloudflare-protected; bot handles CF challenges automatically.</li></ul><h3 id="proshop" tabindex="-1">Proshop <a class="header-anchor" href="#proshop" aria-label="Permalink to &quot;Proshop&quot;">​</a></h3><ul><li>New module: <a href="/AxgstAIO-docs/sites/proshop">Proshop</a> (<code>proshop</code> / <code>ps</code>) — German/Austrian/Polish/Dutch electronics store.</li><li><strong><code>buy</code> mode</strong> — fresh login, ATC, drives the checkout, webhooks the PayPal handoff URL.</li><li><strong><code>register</code> mode</strong> — creates the account and writes the shipping address to the customer profile. Account is immediately ready for <code>buy</code>.</li><li><strong><code>addy_fix</code> mode</strong> — for accounts without a saved address; logs in and posts the address form once.</li><li><strong>Pickup mode</strong> — <code>sizes=pickup</code> + <code>postal_code</code> finds the nearest DPD pickup shop.</li><li><strong>Keyword monitoring</strong> — put a keyword in the URL column instead of a product link; the bot polls Proshop search until a match appears.</li><li>Multi-TLD: <code>.de</code>, <code>.at</code>, <code>.pl</code>, <code>.nl</code> — auto-detected from the product URL or set via the site code.</li></ul><h2 id="v1-8-0-—-colorskates-module-greek-hypercenter-shop" tabindex="-1">v1.8.0 — Colorskates module (Greek Hypercenter shop) <a class="header-anchor" href="#v1-8-0-—-colorskates-module-greek-hypercenter-shop" aria-label="Permalink to &quot;v1.8.0 — Colorskates module (Greek Hypercenter shop)&quot;">​</a></h2><ul><li><p>New module: <a href="/AxgstAIO-docs/sites/colorskates">Colorskates</a> (<code>colorskates</code> / <code>cs</code>) — Greek skate shop on the Hypercenter / osCommerce platform.</p></li><li><p><strong><code>buy</code> mode</strong> — login (cached ~12h), ATC, shipping → payment via Cardlink (Alpha Bank ePOS). The bot self-submits the order to the Alpha Bank gateway and webhooks the resulting session URL — open it in a browser, enter card, done.</p></li><li><p><strong><code>register</code> mode</strong> — full registration with address. reCAPTCHA v2 (invisible flavor) is solved via CapSolver.</p></li><li><p><strong><code>presolve</code> mode</strong> — keeps a small bank of payment-page captcha tokens ready in the background so a buy task doesn&#39;t wait on CapSolver during a hyped drop. Bank size from <code>captcha_bank_size</code> in <code>config.ini</code>.</p></li><li><p>Cloudflare passes via the shared <code>cf_solver</code> (same one Pagro uses).</p></li><li><p>Cart is auto-cleared after login so a previous failed run doesn&#39;t stack stale lines onto the new order.</p></li><li><p>New module: <a href="/AxgstAIO-docs/sites/skstore">SK Store / WSS</a> (<code>skstore</code> / <code>wss</code>) — both shops covered with one module. Guest checkout (no account needed), country-aware shipping (PL → InPost paczkomat; CZ/SK/DE/AT/HU/RO/LT → DHL Europa), discount codes, PayPal payment.</p></li><li><p><strong>CapSolver presolve</strong> for SK Store finalisation: the captcha is solved in the background while the bot fills address + payment, saving ~10–15s per order. Falls back to a manual finalise link if CapSolver is unavailable.</p></li><li><p><a href="/AxgstAIO-docs/sites/footshop">Footshop</a> tweaks: success webhook fires immediately after the order is created; CC vs COD is now picked from the CSV <code>card_number</code> column.</p></li><li><p>Sites menu now lists every supported shop alphabetically.</p></li></ul><h2 id="v1-6-4-—-skatedeluxe-sizing-fix-skateboard-griptape-bundling" tabindex="-1">v1.6.4 — Skatedeluxe sizing fix + skateboard griptape bundling <a class="header-anchor" href="#v1-6-4-—-skatedeluxe-sizing-fix-skateboard-griptape-bundling" aria-label="Permalink to &quot;v1.6.4 — Skatedeluxe sizing fix + skateboard griptape bundling&quot;">​</a></h2><ul><li><a href="/AxgstAIO-docs/sites/skatedeluxe">Skatedeluxe</a>: fixed an issue where every product looked OOS after a site update (sizes were being read from the old page layout).</li><li>Skateboard decks now automatically include the required griptape in the cart.</li><li>Cart is cleared at the start of every buy run, so a previous failed attempt no longer stacks duplicate lines onto the new order.</li><li>Cleaner product names in the logs (no more <code>Shop … online | skatedeluxe</code> wrapper).</li><li>More reliable success/failure detection at checkout — the bot no longer reports &quot;Successful checkout&quot; when the server actually bounced you back to the address or payment page.</li></ul><h2 id="v1-6-3-—-skatedeluxe-register-tolerate-older-csvs" tabindex="-1">v1.6.3 — Skatedeluxe register: tolerate older CSVs <a class="header-anchor" href="#v1-6-3-—-skatedeluxe-register-tolerate-older-csvs" aria-label="Permalink to &quot;v1.6.3 — Skatedeluxe register: tolerate older CSVs&quot;">​</a></h2><ul><li>Fix: the address-save step right after Skatedeluxe register no longer crashes when the CSV doesn&#39;t include a <code>date_of_birth</code> column. A placeholder is used instead.</li></ul><h2 id="v1-6-2-—-skatedeluxe-register-endpoint" tabindex="-1">v1.6.2 — Skatedeluxe register endpoint <a class="header-anchor" href="#v1-6-2-—-skatedeluxe-register-endpoint" aria-label="Permalink to &quot;v1.6.2 — Skatedeluxe register endpoint&quot;">​</a></h2><ul><li>Skatedeluxe split register and login on their backend. The bot was updated to use the new register endpoint, so creating accounts works again.</li></ul><h2 id="v1-6-1-—-skatedeluxe-register-captcha-update" tabindex="-1">v1.6.1 — Skatedeluxe register captcha update <a class="header-anchor" href="#v1-6-1-—-skatedeluxe-register-captcha-update" aria-label="Permalink to &quot;v1.6.1 — Skatedeluxe register captcha update&quot;">​</a></h2><ul><li>Skatedeluxe migrated their register-time captcha. The bot&#39;s CapSolver call was updated to match — registrations work again.</li></ul><h2 id="v1-6-0-—-footshop-module-cod-home-delivery-prague-pickup-register" tabindex="-1">v1.6.0 — Footshop module (COD home delivery + Prague pickup + register) <a class="header-anchor" href="#v1-6-0-—-footshop-module-cod-home-delivery-prague-pickup-register" aria-label="Permalink to &quot;v1.6.0 — Footshop module (COD home delivery + Prague pickup + register)&quot;">​</a></h2><ul><li>New module: <a href="/AxgstAIO-docs/sites/footshop">Footshop</a> (<code>footshop</code> / <code>fs</code>) — covers both <code>footshop.cz</code> and <code>footshop.eu</code> with one module. CSV <code>country_code</code> picks the storefront (<code>CZ</code> → CZK, anything else → EUR).</li><li><strong><code>buy</code> mode</strong> — home delivery via GLS courier with <strong>Dobírka (cash on delivery)</strong>.</li><li><strong><code>pickup</code> mode</strong> — Prague store pickup (Footshop Praha — Na Příkopě, fallback QNS Store 28. října).</li><li><strong><code>register</code> mode</strong> — creates the account; the address from the CSV is saved automatically on first checkout, so subsequent buys skip the address form.</li><li>Login session is cached for ~6h.</li></ul><h2 id="v1-5-4-—-pagro-session-self-heal" tabindex="-1">v1.5.4 — Pagro session self-heal <a class="header-anchor" href="#v1-5-4-—-pagro-session-self-heal" aria-label="Permalink to &quot;v1.5.4 — Pagro session self-heal&quot;">​</a></h2><ul><li><a href="/AxgstAIO-docs/sites/pagro">Pagro</a>: cached sessions now recover automatically when the server has cleaned up the cart in the background. No more &quot;no active cart&quot; failures after the bot has been idle for a while.</li></ul><h2 id="v1-5-3-—-skatedeluxe-module-cc-bank-transfer-register" tabindex="-1">v1.5.3 — Skatedeluxe module (CC + bank transfer + register) <a class="header-anchor" href="#v1-5-3-—-skatedeluxe-module-cc-bank-transfer-register" aria-label="Permalink to &quot;v1.5.3 — Skatedeluxe module (CC + bank transfer + register)&quot;">​</a></h2><ul><li>New module: <a href="/AxgstAIO-docs/sites/skatedeluxe">Skatedeluxe</a> (<code>skatedeluxe</code> / <code>sd</code>).</li><li><strong><code>buy</code> mode</strong> — credit-card checkout (card details from the CSV).</li><li><strong><code>bank</code> mode</strong> — bank transfer / Vorkasse (DE addresses only).</li><li><strong><code>register</code> mode</strong> — creates the account and saves the CSV address as the customer&#39;s default in one go, so subsequent buys go straight to checkout.</li><li>Login session cached for 24h.</li></ul><h2 id="v1-5-2-—-pagro-speedups" tabindex="-1">v1.5.2 — Pagro speedups <a class="header-anchor" href="#v1-5-2-—-pagro-speedups" aria-label="Permalink to &quot;v1.5.2 — Pagro speedups&quot;">​</a></h2><ul><li><a href="/AxgstAIO-docs/sites/pagro">Pagro</a>: faster end-to-end buy flow with fewer requests per order. Saferpay redirect URL is fetched directly instead of going through fallbacks.</li><li>Card brand (Visa / Mastercard) is now auto-detected from the CSV <code>card_number</code> column.</li><li>Persistent login session — second buy on the same account skips both the Cloudflare solve and the login.</li></ul><h2 id="v1-5-1-—-pagro-module-card-payment-via-saferpay" tabindex="-1">v1.5.1 — Pagro module (card payment via Saferpay) <a class="header-anchor" href="#v1-5-1-—-pagro-module-card-payment-via-saferpay" aria-label="Permalink to &quot;v1.5.1 — Pagro module (card payment via Saferpay)&quot;">​</a></h2><ul><li>New module: <a href="/AxgstAIO-docs/sites/pagro">Pagro</a> (<code>pagro</code> / <code>pg</code>) — Austrian shop. Buy + register modes.</li><li>Card payment is finalised on Saferpay&#39;s hosted page — the bot posts the URL to your webhook, you complete the card step in a browser.</li><li>Cloudflare Turnstile is solved automatically. Auth-required proxies are supported.</li><li>A global cap of <strong>5 simultaneous Cloudflare solves</strong> prevents a large task fleet from overloading a small server. Tasks past the cap wait their turn.</li><li>Out-of-stock items auto-retry at the CSV <code>delay</code> interval until restock.</li></ul><h2 id="v1-5-0-—-elbenwald-register-mode" tabindex="-1">v1.5.0 — Elbenwald register mode <a class="header-anchor" href="#v1-5-0-—-elbenwald-register-mode" aria-label="Permalink to &quot;v1.5.0 — Elbenwald register mode&quot;">​</a></h2><ul><li>New <code>register</code> mode for <a href="/AxgstAIO-docs/sites/elbenwald">Elbenwald</a> — pure HTTP, no browser needed. CapSolver is used for the register-time captcha.</li><li>Login / ATC captcha is now solved locally (no CapSolver cost on every buy run — see v1.4.9).</li></ul><h2 id="v1-4-9-—-faster-local-captcha-solving-elbenwald" tabindex="-1">v1.4.9 — Faster local captcha solving (Elbenwald) <a class="header-anchor" href="#v1-4-9-—-faster-local-captcha-solving-elbenwald" aria-label="Permalink to &quot;v1.4.9 — Faster local captcha solving (Elbenwald)&quot;">​</a></h2><ul><li><a href="/AxgstAIO-docs/sites/elbenwald">Elbenwald</a>&#39;s FriendlyCaptcha is now solved <strong>locally</strong> in ~0.1–0.7s instead of going through CapSolver (~3–5s + per-solve cost). No CSV / config changes needed.</li></ul><h2 id="v1-4-8-—-generic-queue-it-module" tabindex="-1">v1.4.8 — Generic Queue-it module <a class="header-anchor" href="#v1-4-8-—-generic-queue-it-module" aria-label="Permalink to &quot;v1.4.8 — Generic Queue-it module&quot;">​</a></h2><ul><li>New module: <a href="/AxgstAIO-docs/sites/queueit">Queue-it (generic)</a> (<code>qit</code> / <code>queueit</code>) — paste any <code>*.queue-it.net</code> queue URL into the CSV and the bot waits in the queue, then sends the <strong>pass link</strong> to your webhook. Open it in a real browser within 1–5 min and you&#39;re past the queue.</li><li>Works for any Queue-it customer (Supreme, Adidas, Ticketmaster, public-sector portals, …) — no per-site module needed.</li><li>For full end-to-end automation through a queued site, prefer the per-site module (e.g. <a href="/AxgstAIO-docs/sites/ipzs">IPZS</a>) which handles queue + ATC + checkout in one task.</li></ul><h2 id="v1-4-7-—-ipzs-module" tabindex="-1">v1.4.7 — IPZS module <a class="header-anchor" href="#v1-4-7-—-ipzs-module" aria-label="Permalink to &quot;v1.4.7 — IPZS module&quot;">​</a></h2><ul><li>New module: <a href="/AxgstAIO-docs/sites/ipzs">IPZS</a> — Italian State Mint, numismatic &amp; commemorative coin shop. Buy mode only — register the account manually on the site, then plug the credentials into the CSV.</li><li>Handles Queue-it gating on hyped drops automatically.</li><li>Out-of-stock retry — the bot keeps retrying ATC at the CSV <code>delay</code> interval, picking up live restocks during a drop.</li><li>PayPal Express checkout — approval URL is sent to the webhook.</li></ul><h2 id="v1-4-6-—-catchyourcards-module" tabindex="-1">v1.4.6 — CatchYourCards module <a class="header-anchor" href="#v1-4-6-—-catchyourcards-module" aria-label="Permalink to &quot;v1.4.6 — CatchYourCards module&quot;">​</a></h2><ul><li>New module: <a href="/AxgstAIO-docs/sites/catchyourcards">CatchYourCards</a> — Pokémon TCG / One Piece / Lorcana store. ~3–4 s end-to-end after Cloudflare clearance.</li><li><code>test</code> mode — probes all ATC paths and writes a debug log; useful during a real Queue-Fair drop to validate which paths still work.</li><li>Auth-required proxies supported (no Chrome auth-dialog popup).</li><li>Mollie iDEAL payment URL is sent to the webhook.</li></ul><h2 id="v1-4-5-—-elbenwald-checkout-fix" tabindex="-1">v1.4.5 — Elbenwald checkout fix <a class="header-anchor" href="#v1-4-5-—-elbenwald-checkout-fix" aria-label="Permalink to &quot;v1.4.5 — Elbenwald checkout fix&quot;">​</a></h2><ul><li>Order creation is now reliable — line items no longer silently dropped at checkout, cart no longer goes empty after captcha solve.</li><li>Switched to PayPal Express — bot returns the PayPal URL on the webhook, you authorise to complete the order.</li><li>Cart is cleared on each run so previous attempts don&#39;t stack onto the new order.</li></ul><h2 id="v1-4-4-—-empik-price-monitor-rewrite" tabindex="-1">v1.4.4 — Empik price monitor rewrite <a class="header-anchor" href="#v1-4-4-—-empik-price-monitor-rewrite" aria-label="Permalink to &quot;v1.4.4 — Empik price monitor rewrite&quot;">​</a></h2><ul><li>Long-running price monitors now use ~450× less proxy bandwidth per tick.</li><li>Auto-rotates proxies on rate-limit / ban responses instead of hammering a dead IP.</li></ul><h2 id="v1-4-3-—-games-island-bandwidth-savings" tabindex="-1">v1.4.3 — Games Island + bandwidth savings <a class="header-anchor" href="#v1-4-3-—-games-island-bandwidth-savings" aria-label="Permalink to &quot;v1.4.3 — Games Island + bandwidth savings&quot;">​</a></h2><ul><li>New module: <a href="/AxgstAIO-docs/sites/gamesisland">Games Island</a> — TCG / tabletop / board games store. Register + auto-saved address + reCAPTCHA v2. Checkout via Vorkasse (bank transfer).</li><li>Empik price monitor: per-hour proxy usage on long monitor runs is now ~2–4 MB instead of ~480 MB.</li><li>Empik buy: stops re-fetching the product page on every retry — falls back to the lighter price monitor.</li><li>BasketballEmotion + FutbolEmotion: drop-wait loop is now ~800× lighter on bandwidth.</li></ul><h2 id="v1-2-1-—-cleaner-log-output" tabindex="-1">v1.2.1 — Cleaner log output <a class="header-anchor" href="#v1-2-1-—-cleaner-log-output" aria-label="Permalink to &quot;v1.2.1 — Cleaner log output&quot;">​</a></h2><ul><li>Removed debug prints, entry banners, and the PayPal URL from the console (still posted to webhooks).</li><li>Unified log style across all modules: <code>Restored session</code> / <code>Found: &lt;name&gt;</code> / <code>Size: &lt;x&gt;</code> / <code>Successful checkout (Ns)</code>.</li><li>No functional changes.</li></ul><h2 id="v1-2-0-—-checkout-reliability" tabindex="-1">v1.2.0 — Checkout reliability <a class="header-anchor" href="#v1-2-0-—-checkout-reliability" aria-label="Permalink to &quot;v1.2.0 — Checkout reliability&quot;">​</a></h2><ul><li>Eliminates the <code>order-token-expired</code> errors at place-order on Zalando.</li></ul><h2 id="v1-1-9-—-faster-zalando-checkout" tabindex="-1">v1.1.9 — Faster Zalando checkout <a class="header-anchor" href="#v1-1-9-—-faster-zalando-checkout" aria-label="Permalink to &quot;v1.1.9 — Faster Zalando checkout&quot;">​</a></h2><ul><li>~6 s faster end-to-end on Zalando — login + product fetch and several other steps now run in parallel.</li></ul><h2 id="v1-1-8-—-experimental-rolled-back-in-v1-2-0" tabindex="-1">v1.1.8 — Experimental (rolled back in v1.2.0) <a class="header-anchor" href="#v1-1-8-—-experimental-rolled-back-in-v1-2-0" aria-label="Permalink to &quot;v1.1.8 — Experimental (rolled back in v1.2.0)&quot;">​</a></h2><ul><li>Tried to skip a checkout step. Caused <code>order-token-expired</code> errors. Reverted.</li></ul><h2 id="v1-1-7-—-better-zalando-address-detection" tabindex="-1">v1.1.7 — Better Zalando address detection <a class="header-anchor" href="#v1-1-7-—-better-zalando-address-detection" aria-label="Permalink to &quot;v1.1.7 — Better Zalando address detection&quot;">​</a></h2><ul><li>Broader check for &quot;address present&quot; in Zalando checkout state. Folded into v1.2.1.</li></ul><h2 id="v1-1-6-—-abort-on-login-failure" tabindex="-1">v1.1.6 — Abort on login failure <a class="header-anchor" href="#v1-1-6-—-abort-on-login-failure" aria-label="Permalink to &quot;v1.1.6 — Abort on login failure&quot;">​</a></h2><ul><li>Tasks now abort immediately on login failure instead of pointlessly continuing to probe + ATC.</li></ul><h2 id="v1-1-5-—-zalando-login-fix" tabindex="-1">v1.1.5 — Zalando login fix <a class="header-anchor" href="#v1-1-5-—-zalando-login-fix" aria-label="Permalink to &quot;v1.1.5 — Zalando login fix&quot;">​</a></h2><ul><li>Fixed a Zalando login that started failing after a server-side change.</li></ul><h2 id="v1-1-4-—-cleaner-errors-on-flagged-proxies" tabindex="-1">v1.1.4 — Cleaner errors on flagged proxies <a class="header-anchor" href="#v1-1-4-—-cleaner-errors-on-flagged-proxies" aria-label="Permalink to &quot;v1.1.4 — Cleaner errors on flagged proxies&quot;">​</a></h2><ul><li>Akamai-blocked responses now print a clear <code>halt</code> message instead of an unhandled exception.</li></ul><h2 id="v1-1-3-—-zalando-login-back-to-web-flow" tabindex="-1">v1.1.3 — Zalando login back to web flow <a class="header-anchor" href="#v1-1-3-—-zalando-login-back-to-web-flow" aria-label="Permalink to &quot;v1.1.3 — Zalando login back to web flow&quot;">​</a></h2><ul><li>Mobile OAuth login was failing consistently with <code>XSRF validation failed</code>. Login is back on the stable web flow. Register still uses mobile.</li></ul><h2 id="v1-1-2-—-update-mechanism-fix-winerror-183" tabindex="-1">v1.1.2 — Update mechanism fix (WinError 183) <a class="header-anchor" href="#v1-1-2-—-update-mechanism-fix-winerror-183" aria-label="Permalink to &quot;v1.1.2 — Update mechanism fix (WinError 183)&quot;">​</a></h2><ul><li>Auto-update no longer fails with <code>Cannot create a file when that file already exists</code>. See <a href="/AxgstAIO-docs/guide/updating#winerror-183-cannot-create-a-file-when-that-file-already-exists">Updating</a> for the manual cleanup if you&#39;re still on v1.1.1 or older.</li></ul><h2 id="v1-1-0–1-1-1-—-zalando-mobile-sso" tabindex="-1">v1.1.0–1.1.1 — Zalando mobile SSO <a class="header-anchor" href="#v1-1-0–1-1-1-—-zalando-mobile-sso" aria-label="Permalink to &quot;v1.1.0–1.1.1 — Zalando mobile SSO&quot;">​</a></h2><ul><li>First attempt at mobile-Android login flow for Zalando. Login still failed with XSRF — see v1.1.3 for the fix.</li></ul><h2 id="v1-0-9-and-earlier" tabindex="-1">v1.0.9 and earlier <a class="header-anchor" href="#v1-0-9-and-earlier" aria-label="Permalink to &quot;v1.0.9 and earlier&quot;">​</a></h2><p>Initial releases. Basic support for Zalando, SportsShoes, Empik, BasketballEmotion, FutbolEmotion. No auto-update.</p>',69)])])}const g=o(l,[["render",i]]);export{p as __pageData,g as default};
